quests[29571] = { id = 29571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Wildnis", description = "Der Irdene Ring arbeitet oft eng mit dem Zirkel des Cenarius zusammen. So ist es auch dieses Mal.\n\nReist nach Norden zum Tiefensumpf und sprecht mit Behüterin Jhang. Sie leitet eine Expedition in den Echsenkessel, um die Naga aufzuhalten und die Zangarmarschen zu retten.", sourceObjective = "Sprecht mit Behüterin Jhang im Tiefensumpf.", completion = "Der Tiefensumpf steht kurz davor, zu einem Teil des Systems zu werden, das die Naga im Echsenkessel etabliert haben. Ihr müsst uns helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29573] = { id = 29573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit geht vor", description = "Es ist hier jetzt fast so sicher, dass meine Leute kommen und sich holen können, was rechtmäßig ihnen gehört. Die einzig große, noch verbleibende Gefahr stellt Shaffars Leibgarde dar. Von der wimmelt es hier.\n\nKümmert Euch um diese Streitkräfte, während ich wieder zu Kräften komme.", sourceObjective = "Tötet 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder. Kehrt danach zu Konstrukteur Morphalius zurück.", completion = "Wunderbar! Haramad wird sich über die guten Neuigkeiten freuen! Dieser Ort wird ihm wie ein reifer Apfel in die Hand fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29574] = { id = 29574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rätselhafte Wesen", description = "Nahe des Eingangs dieser Hallen gibt es eine Kreatur, die Pandemonius genannt wird. Sie ist in der Lage, die Energien der Leere so zu verändern, dass sie sich daraus versorgen und stärken kann.\n\nWeiter hinten liegt Tavarok, ein Wesen, das die gleiche Energie in eine kristalline Struktur umwandelt, die stärker ist als alles, was ich je gesehen habe!\n\nIch brauche dringend Proben für weitere Untersuchungen.", sourceObjective = "Bringt Pandemonius' Essenz und Tavaroks Herz zu Mamdy dem Ologen.", progress = "Wenn Ihr nicht habt, wonach ich suche, verschwendet Ihr nur meine Zeit.", completion = "Diese Proben sind äußerst interessant. Sie werden mir sehr helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29575] = { id = 29575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Konkurrenz untergraben", description = "Dank der Barriere, die Nexusprinz Shaffar errichtet und der Truppen, die er aufgestellt hat, kann er diese Gruft in aller Seelenruhe ausplündern.\n\nNexusprinz Haramad ist darüber nicht gerade begeistert. Deshalb hat er einen sehr ansehnlichen Preis auf Shaffars Kopf ausgesetzt.", sourceObjective = "Bringt Shaffars Bandagen zu Konstrukteur Morphalius.", progress = "Hattet Ihr Euch für den Preis auf Shaffars Kopf interessiert?", completion = "Ich hätte nicht gedacht, dass ein {race} einen Nexusprinzen besiegen kann. Ihr habt mich überrascht und Euch diese schöne Belohnung mehr als verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[29582] = { id = 29582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greks verrückte Nacht", description = "Grek hatte gestern ziemlich üble Nacht.\n\nGlänzender Mumienmann kam in Greks Haus und sagte, Grek solle zu Managruft in Auchindoun gehen. Aber Grek versuchte noch Steckbrief zu lesen!\n\n<Greks Augen beginnen zu leuchten.>\n\nGrek weiß! Ihr gehen zu glänzendem Mumienmann und sagt ihm, Grek schickt Euch. Perfekter Plan!", sourceObjective = "Sprecht mit Konstrukteur Morphalius in der Managruft in Auchindoun.", sourceObjectiveStatus = "unverified-source-field" }
quests[29583] = { id = 29583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eckert der Verrückte", description = "Ich bin ein erfahrener Ingenieur, ein brillanter Erfinder, der Mittelpunkt jeder Party und der beste Tänzer, den es jemals in Azeroth gegeben hat.\n\nAber nennt mich jemand so? Nein.\n\nDa hat man nur eine Begegnung mit einem Astralen und auf einmal nennt einen die ganze Welt \"den Verrückten\".\n\nGenau hier habe ich gestern einen gesehen, das schwöre ich! Er sagte, ich müsste ihm nur zur Managruft in Auchindoun folgen, dann würde ich einen gewaltigen Schatz bekommen und uraltes Wissen erlangen!", sourceObjective = "Sprecht mit Konstrukteur Morphalius in der Managruft in Auchindoun.", completion = "Ich hatte wirklich gehofft, dass der Gnom, den ich aufgesucht habe, meinem Ruf folgen würde.\n\n<Konstrukteur Morphalius mustert Euch.>\n\nNa ja, Ihr müsst mir genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29590] = { id = 29590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Totenwächter", description = "Ein schreckliches, überirdisches Wesen sucht die Welt der Geister und die der Lebenden heim. Wir nennen es Shirrak.\n\nEs kann nur in Eurem Reich verletzt werden. Bitte helft uns, diesen Alptraum zu beenden.", sourceObjective = "Tötet Shirrak den Totenwächter und kehrt zu dem Draeneigeist zurück.", completion = "Vielleicht werden wir jetzt endlich Frieden finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29591] = { id = 29591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Geister", description = "Die Auchenai haben all unseren Werten den Rücken gekehrt. Sie erwecken die Toten und halten sie als ihre unheiligen Diener!\n\nDas muss ein Ende haben. Bringt diesen Geistern den Frieden und tötet alle, die sie zu Untoten gemacht haben.", sourceObjective = "Tötet 5 erboste Skelette, 5 tobende Skelette und 3 Totenbeschwörer der Auchenai. Kehrt dann zur gequälten Seelenpriesterin in der Auchenaikrypta zurück.", completion = "Die Toten gehören ins Reich der Geister, so wie Ihr in dieses Reich gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[29593] = { id = 29593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft sie, wo es schmerzt", description = "Die Höllenorcs lagern eine Menge Vorräte hier.\n\nEs würde ihren Feldzug empfindlich treffen und unserem deutlich helfen, wenn sie gestohlen würden. Traut Ihr Euch das zu, {class}?", sourceObjective = "Stehlt 3 Stapel Vorräte der Höllenfeuerhalbinsel und kehrt zu Steingardist Stok'ton im Höllenfeuerbollwerk zurück.", progress = "Wie viele Vorräte konntet Ihr mitnehmen?", completion = "Sehr gut! Langfristig wird dieser Angriff weit schwerwiegendere Konsequenzen haben als der Tod von ein paar Orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[29594] = { id = 29594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft sie, wo es schmerzt", description = "Die Höllenorcs lagern eine Menge Vorräte hier.\n\nEs würde ihren Feldzug empfindlich treffen und unserem deutlich helfen, wenn sie gestohlen würden. Traut Ihr Euch das zu, {class}?", sourceObjective = "Stehlt 3 Stapel Vorräte der Höllenfeuerhalbinsel und kehrt zu Vorhutsspäher Chadwick im Höllenfeuerbollwerk zurück.", progress = "Wie viele Vorräte konntet Ihr mitnehmen?", completion = "Sehr gut! Langfristig wird dieser Angriff weit schwerwiegendere Konsequenzen haben als der Tod von ein paar Orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[29595] = { id = 29595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles wird gut", description = "Da habt Ihr ja ein ziemliches Abenteuer hinter Euch, {name}. Dabei habt Ihr die Auchenaikrypta noch nicht einmal betreten.\n\nIch bin einer der glücklichen Geister. Ich war nie an Levixus gebunden, noch war ich Teil von Exarch Maladaars verwerflichen Experimenten in der Nekromantie. Levixus habt Ihr bereits vernichtet, aber Maladaar quält weiter die Geister in der Krypta.\n\nIch habe eine simple Bitte an Euch. Betretet die Auchenaikrypta und sprecht mit dem Draeneigeist dort. Ihr müsst Exarch Maladaar vernichten.", sourceObjective = "Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr in die Auchenaikrypta geht und Exarch Maladaar vernichtet.", completion = "Willkommen in der Auchenaikrypta, {name}. Unsere beiden Welten treffen sich hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[29596] = { id = 29596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Exarchen", description = "Exarch Maladaar übt sein unheiliges Werk im tiefsten Teil der Krypta aus. Er stellt eine Bedrohung für unser beider Welten dar und muss aufgehalten werden.\n\nTötet ihn zum Wohle aller, dem der Toten und dem der Lebenden.", sourceObjective = "Tötet Exarch Maladaar und kehrt zu dem Draeneigeist in der Auchenaikrypta zurück.", completion = "Ihr habt unserem Reich einen großen Dienst erwiesen. Wir werden Euch nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29598] = { id = 29598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarethas Ablenkungsmanöver", description = "Taretha war es, die ursprünglich für das Ablenkungsmanöver in Durnholde sorgte und Thrall die Flucht ermöglichte.\n\nNun haben die Ewigen Taretha gefangen genommen. Wenn wir nicht eingreifen, wird es kein Ablenkungsmanöver geben. Nehmt die Brandsätze, die ich Euch gegeben habe, und brennt die Internierungsbaracken nieder.", sourceObjective = "Reist nach Burg Durnholde und platziert mithilfe des Bündels mit Brandbomben, das Ihr von Erozion erhalten habt, 5 Brandsätze auf den Fässern in jeder Internierungsbaracke.\n\nSprecht mit Thrall im Kellergefängnis von Burg Durnholde, wenn Ihr die Internierungsbaracken angezündet habt.", progress = "Wer seid Ihr?", completion = "Ihr seid mit Taretha befreundet? Das ist also ihr neuer Plan. Nun gut…", sourceObjectiveStatus = "unverified-source-field" }
quests[29599] = { id = 29599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Durnholde", description = "Ich habe große Pläne für mein Volk, <Fremder/Fremde>.\n\nEines Tages wird es seine Unterdrücker stürzen und sich erheben. Es wird die Ketten sprengen, die es halten und dies wird die Geburtsstunde der orcischen Horde sein.\n\nWir fliehen, wenn Ihr bereit seid.", sourceObjective = "Gebt Thrall Bescheid, wenn Ihr bereit seid. Folgt Thrall aus der Burg Durnholde und helft ihm, Taretha zu befreien und sein Schicksal zu erfüllen.\n\nSprecht mit Erozion im Alten Hügelland, wenn Ihr diese Aufgabe erfüllt habt.", completion = "Ihr habt eine großartige Aufgabe vollbracht, {name}. Nun müssen die Erinnerungen des jungen Kriegshäuptlings an diese Ereignisse wieder so verändert werden, wie sie einst waren...", sourceObjectiveStatus = "unverified-source-field" }
quests[29605] = { id = 29605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder gegen Bruder", description = "Die Sethekk verließen Skettis, als Auchindoun explodierte.\n\nMein Bruder Syth gehörte zu ihren Anführern. Auf seinen Befehl suchten wir die Ruinen auf und stellten uns unserem Gott.\n\nNach kurzer Zeit warf mich Syth jedoch aus den Hallen, weil mir Zweifel an ihren Fähigkeiten kamen. Er erlaubte mir nicht, meine Schwester Lakka mitzunehmen. Werdet Ihr mir helfen, sie zu retten?", sourceObjective = "Befreit Lakka aus ihrer Gefangenschaft. Kehrt zu Isfar in den Sethekkhallen zurück, wenn Ihr die Rettung abgeschlossen habt.", completion = "Zu wissen, dass Lakka frei ist, bedeutet, dass ich endlich all meine Bande zu den Sethekk abwerfen kann.\n\nEin Teil von mir wird mir Syths Tod niemals verzeihen, aber es musste getan werden. Ich werde die Todesriten für ihn vollziehen, wenn ich in Skettis ankomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[29606] = { id = 29606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokks Erbe", description = "Terokk, der Held von Arakkoa, verschwand eines Tages plötzlich und ließ nur seine Maske und seinen Speer zurück.\n\nDunkelwirker Syth hat sie immer noch in seinem Besitz und Klauenkönig Ikiss wacht über seinen Speer.\n\nEs würde meinem Volk viel bedeuten, wenn wir die Gegenstände zurückbekommen würden.", sourceObjective = "Bringt Terokks Maske und Terokks Federkiel zu Isfar in den Sethekkhallen.", progress = "Die Relikte von Terokk sind schon viel zu lange aus Skettis fort. Konntet Ihr sie von den Sethekk zurückholen?", completion = "Vielleicht wird mir meine Rolle bei den Verbrechen der Sethekk niemals vergeben werden, aber ich möchte versuchen, meine Sünden zu büßen, indem ich die Relikte von Terokk meinem Volk zurückgebe", sourceObjectiveStatus = "unverified-source-field" }
quests[29607] = { id = 29607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen der Begierde", description = "Ich habe einen Kunden, der sich für die Augen der kobaltblauen Schlangen interessiert, die sich hier angesiedelt haben.\n\nWenn Ihr mir einige dieser seltenen Edelsteine besorgen könntet, würde ich den Profit mit Euch teilen.\n\nEinverstanden?", sourceObjective = "Händler Vijaad in den Sethekkhallen möchte, dass Ihr ihm 3 Kobaltaugen bringt.", progress = "Habt Ihr die Augen bekommen?", completion = "Wunderbare Stücke, gut gemacht!\n\nHier ist Euer Anteil, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29608] = { id = 29608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete in Dalaran", description = "Willkommen in Nordend, {name}. Man hat mich gebeten, die Reise nach Dalaran für Euch zu arrangieren, damit Ihr dort unsere Verbündeten treffen könnt.\n\nReitet auf einem Greifen nach Dalaran und sucht nach der Landung unser Gasthaus Zum Gefeierten Helden auf. Sprecht dort mit Isirami Sanftwind.\n\nSie wird Euch dabei helfen, Euren Ruhestein an die Stadt zu binden. Mit dem Portal in der Silbernen Enklave könnt Ihr dann rasch nach Sturmwind zurückreisen.", sourceObjective = "Macht einen Greifenritt nach Dalaran und sprecht mit Isirami Sanftwind im Gasthaus Zum Gefeierten Helden.", completion = "Willkommen in Dalaran! Dieses Gasthaus gehört zur Silbernen Enklave, dem offiziellen Hauptquartier der Allianz in dieser Stadt.\n\nVergesst nicht, Euren Ruhestein hier zu binden, damit Ihr rasch in die Stadt reisen und nebenan das Portal nach Sturmwind nutzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29609] = { id = 29609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde in Dalaran", description = "Willkommen in Nordend. Man hat mich gebeten, Eure Reise nach Dalaran zu arrangieren, damit Ihr unsere Freunde in der Stadt kennenlernen könnt.\n\nSprecht mit mir und nehmt einen Flug nach Dalaran an. Begebt Euch nach der Landung zum Gasthaus \"Das Rattenloch\".\n\nRedet dort mit Uda dem Biest.\n\nSie wird Euch dabei helfen, Euren Ruhestein an die Stadt zu binden. Dann könnt Ihr durch das Portal in Sonnenhäschers Zuflucht rasch nach Orgrimmar reisen.", sourceObjective = "Lasst Euch vom Flugmeister einen Flug nach Dalaran geben und sprecht mit Uda dem Biest im Rattenloch.", completion = "Ich habe Euch erwartet. Dieses Gasthaus gehört zu Sonnenhäschers Zuflucht, der Hordenenklave von Dalaran.\n\nDenkt daran, Euren Ruhestein hier zu binden, damit Ihr rasch zur Stadt kommen und das Portal nach Orgrimmar, draußen neben dem Brunnen, benutzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29613] = { id = 29613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gerechtes Schicksal", description = "Kriegsherr Kalithresh leitet Operation Dampfkammer.\n\nEr muss sterben, {name}. Die Naga lassen uns keine andere Wahl als Gewalt.\n\nZeigt ihm keine Gnade.", sourceObjective = "Tötet Kriegsherr Kalithresh und kehrt zu Behüterin Jhang in der Dampfkammer zurück.", completion = "Ich wünschte, das wäre nicht nötig gewesen, aber die Naga haben alle Verhandlungsangebote abgelehnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29614] = { id = 29614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung ist der Schlüssel", description = "Die Naga haben sich mit den Lepragnomen verbündet, um eine schreckliche Krankheit in den Zangarmarschen zu verbreiten. Man begegnet ihr schon überall im Dampfkessel.\n\nVernichtet alles, das bereits befallen ist, und bringt mir das mittlere Zahnrad von Robogenieur Dampfhammer. Beeilt Euch!", sourceObjective = "Tötet 3 Sumpfoberanführer und 6 Aussätzige des Echsenkessels und erbeutet ein verstrahltes Zahnrad von Robogenieur Dampfhammer. Kehrt dann zu Naturalist Biss zurück.", progress = "Geht so sorgfältig wie möglich vor. Das Schicksal der Zangarmarschen hängt davon ab.", completion = "Ich bin froh, dass wir die Krankheit eingedämmt haben, bevor sie sich in den Zangarmarschen ausbreiten konnte. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29615] = { id = 29615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windrufer Klaue und die Wasserdiebin", description = "Die Naga versuchen schon seit längerem, das Wasser aus den Zangarmarschen abzupumpen. Die Dampfkammer ist der Dreh- und Angelpunkt dieser Operation. Überwacht wird sie von Hydromantin Thespia.\n\nIhr Tod würde die Naga empfindlich treffen.", sourceObjective = "Tötet Hydromantin Thespia und kehrt zu Windrufer Klaue in der Dampfkammer zurück.", completion = "Vielleicht können wir dem Land das verzweifelt benötigte Wasser nun zurückgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29616] = { id = 29616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Dampfkammer", description = "Bisher ist es uns nicht gelungen, die Naga in der Dampfkammer, wo sich ihre Pumpenzentrale befindet, aufzuhalten.\n\nZum Glück versucht die Expedition, die ich ausgesandt habe, das zu ändern. Würdet Ihr Euch in die Dampfkammer begeben und Behüterin Jhang Eure Hilfe anbieten?", sourceObjective = "Sprecht mit Behüterin Jhang in der Dampfkammer.", completion = "Ich danke den Sternen für Euch! Wir benötigen Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29640] = { id = 29640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Spion To'gun", description = "Der Schattenrat hat die meisten unserer Spione bereits getötet, aber To'gun, der fliehen konnte, war so dumm zurückzukehren!\n\nIhr müsst ihn finden. Er ist unvernünftig, aber wir müssen herausfinden, was er weiß.", sourceObjective = "Findet Spion To'gun im Schattenlabyrinth von Auchindoun.", completion = "Wäret Ihr so nett, mir aus dem Käfig zu helfen? Er ist ein wenig beengt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29641] = { id = 29641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeleninstrumente", description = "Sie haben mich gefoltert, damit ich ihnen alles verrate, was ich weiß.\n\nDie anderen haben sie an Höllenschlund verfüttert, ich hätte als nächstes dran sein sollen. Aber ich habe ihnen nichts verraten!\n\nSie benutzen spezielle Geräte, damit ihre Beschwörungen mächtiger werden. Diese Geräte müsst Ihr stehlen!", sourceObjective = "Stehlt 5 Seeleninstrumente und bringt sie zu Spionin Grik'tha im Schattenlabyrinth von Auchindoun.", progress = "Habt Ihr To'gun gefunden?", completion = "Dies sind also die Seeleninstrumente, mit denen der Schattenrat seine Beschwörungskraft erhöht? Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[29642] = { id = 29642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Auchindoun", description = "Meine Spione in Auchindoun haben uns erschreckende Berichte geschickt. Seit seiner Explosion vor ein paar Jahren hat dieser Ort nichts als Ärger gebracht.\n\nDort ist etwas - mal wieder - ganz schön schief gegangen, und der Schattenrat bereitet sich auf einen Krieg vor. Auch wenn die Berichte viele Details verschweigen, müssen sie sich auf einen Krieg im Inneren vorbereiten.\n\nIhr müsst Euch zum Eingang des Schattenlabyrinths begeben. Mein Feldkommandeur, Mahfuun, wird Euch genau erklären, was zu tun ist.", sourceObjective = "Meldet Euch bei Feldkommandeur Mahfuun im Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[29643] = { id = 29643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex des Blutes", description = "Vor zwei Jahren beschwor der Schattenrat ein Wesen, das eine Schneise der Verwüstung in Auchindoun hinterließ.\n\nLest den Kodex des Blutes, um herauszufinden, was damals geschah. Seid jedoch vorsichtig, denn Großmeister Vorpil beschützt ihn mit seinem Leben.", sourceObjective = "Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun.", completion = "Während Ihr den magiegeladenen Folianten öffnet, überkommt Euch ein Gefühl des Schreckens.\n\nIrgendetwas ist hier eindeutig nicht in Ordnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[29644] = { id = 29644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Herz des Labyrinths", description = "Der Schattenrat hat die Kontrolle über das kosmische Wesen, das sie vor fast zwei Jahren beschworen haben, verloren!\n\nMan nennt es Murmur und es droht, den Schattenrat zu überrennen und zu entkommen!", sourceObjective = "Vernichtet Murmur und meldet Euch danach bei Feldkommandeur Mahfuun im Schattenlabyrinth von Auchindoun.", completion = "Ich schüttele mich bei dem Gedanken, was hätte passieren können, wenn Murmur entkommen wäre.\n\nDanke, mutiger Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[29645] = { id = 29645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschafter Höllenschlund", description = "Als die Kabale unsere Spione entdeckte, verfütterte sie alle an Botschafter Höllenschlund.\n\nUnsere Männer verdienen Gerechtigkeit. Tötet die Ritualisten, die Höllenschlund binden und vernichtet dann auch ihn.\n\nEr hat dieses Schicksal schon lange verdient.", sourceObjective = "Tötet 18 Ritualisten der Kabale und Botschafter Höllenschlund. Kehrt dann zu Feldkommandeur Mahfuun im Schattenlabyrinth von Auchindoun zurück.", completion = "Das bringt zwar niemanden zurück, aber wenigstens wurde der Gerechtigkeit Genüge getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29649] = { id = 29649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Leben rettet", description = "Gunny stirbt an einem mächtigen Fluch, {name}.\n\nGroßhexenmeister Nethekurse benutzt zwei mystische Kohlefeuer zur Verstärkung seiner Kräfte. Vielleicht könnten wir mit etwas Glut aus einem Kohlefeuer diese dunkle Magie rückgängig machen.", sourceObjective = "Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr ihm Teufelsglut bringt.", progress = "Habt Ihr die Glut dabei? Wir haben nicht viel Zeit.", completion = "Er war ein guter Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[29650] = { id = 29650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsglut", description = "Caza'rez stirbt wie ein Feigling.\n\nGroßhexenmeister Nethekurse hat ihn mit einem schrecklichen Fluch belegt. Bringt mir etwas Glut aus seinen Kohlenpfannen. Vielleicht können wir die Magie damit umkehren, bevor es zu spät ist.", sourceObjective = "Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr ihm Teufelsglut bringt.", progress = "Habt Ihr die Glut bekommen? Caza'rez verdient es, wie ein Krieger zu sterben.", completion = "Ich werde viele Lieder zu seinem Ruhm anstimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29651] = { id = 29651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Sterbenden", description = "Ihre Elitekrieger sind gnadenlos... so... mächtig.\n\n<Caza'rez spuckt Blut.>\n\nIhr müsst sie töten... sonst werden wir Kargath nie besiegen...", sourceObjective = "Caza'rez in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr 4 Legionäre der Zerschmetterten Hand, 2 Zenturionen der Zerschmetterten Hand und 2 Champions der Zerschmetterten Hand tötet.", completion = "Caza'rez ist... von uns gegangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29652] = { id = 29652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letzter Gefallen", description = "Der alte Gunny macht's nicht mehr lange...\n\nErweist mir einen letzten Gefallen und tötet die größten, übelsten Höllenorcs, die Ihr finden könnt.\n\nIm Andenken an alte Zeiten, ja?", sourceObjective = "Gunny in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr 4 Legionäre, 2 Zenturionen und 2 Champions der Zerschmetterten Hand tötet.", completion = "Hätten wir ihn doch retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29653] = { id = 29653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille des Kriegshäuptlings", description = "Kargath war einst einer der größten Helden der Horde.\n\nDoch nun trägt er den falschen Mantel des Kriegshäuptlings. Bringt mir die nach ihm benannte Waffe, damit wir uns an seine früheren Heldentaten erinnern können und nicht an die Gräuel, die er heute anrichtet.", sourceObjective = "Bringt Kriegshäuptling Kargaths Faust zu Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr einen Beweis für den Sieg über Kargath Messerfaust?", completion = "Wir dürfen den Orc nicht vergessen, der Kargath einst war, noch die Lektion, die uns sein Fall sein sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29654] = { id = 29654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal wenden", description = "Es gibt nur einen Weg, um sicherzustellen, dass die Höllenorcs die Ehrenfeste und die Allianz nicht länger bedrohen.\n\nIhr Kriegshäuptling muss sterben.\n\nBringt mir die Waffe, die nach ihm benannt ist, damit wir seinen Tod niemals vergessen.", sourceObjective = "Bringt Kriegshäuptling Kargaths Faust zu Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr einen Beweis für den Sieg über \"Kriegshäuptling\" Kargath Messerfaust mitgebracht?", completion = "Mit Eurer Hilfe haben wir dem Feind schweren Schaden zugefügt.\n\nDie Ehrenfeste war schon seit Jahren nicht mehr so sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[29655] = { id = 29655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz besonderes Tuch", description = "Kriegshetzer O'mrogg hat mehr mutige Soldaten auf dem Gewissen als jeder andere Feind, dem ich bisher begegnet bin. Er ist skrupellos, listig und äußerst mächtig.\n\nTötet ihn und bringt mir sein Kriegstuch. Wir werden ein Banner daraus nähen, sodass der Zorn der Horde für alle sichtbar ist.", sourceObjective = "Tötet Kriegshetzer O'mrogg und bringt sein Kriegstuch zu Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr das Tuch dabei?", completion = "Sehr gut. Nun werden diese blutgierigen Ungeheuer sehen, mit wem sie sich angelegt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29656] = { id = 29656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O'mroggs Kriegstuch", description = "Sturmwind möchte Beweise für unsere Kriegserfolge sehen.\n\nWir könnten ihm Leichensäcke schicken, aber ich denke, das Kriegstuch von O'mrogg, Kargaths mächtigstem Krieger würde ihn mehr beeindrucken. Traut Ihr ihn Euch zu?", sourceObjective = "Tötet Kriegshetzer O'mrogg und bringt sein Kriegstuch zu Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", progress = "Habt Ihr das Tuch dabei?", completion = "Meine Vorgesetzten werden damit sehr zufrieden sein. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29657] = { id = 29657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus großer Kraft folgt große Verantwortung", description = "<Ihr hört eine Stimme, leicht wie der Klang winziger Glocken, in Eurem Kopf.>\n\nIn der Mechanar entstehen durch die Technologie meines Volks Manazellen, Objekte, die eine gewaltige Energie in sich tragen.\n\nTötet Mechanolord Kapazitus, damit Kael'thas' Streitkräfte sich diese Macht nicht zu Nutze machen können.", sourceObjective = "A'dal bittet Euch, Mechanolord Kapazitus in der Mechanar der Festung der Stürme zu töten.", completion = "Beeindruckend, {name}. Doch es gibt noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[29658] = { id = 29658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kalkulator", description = "<Eine leichte Brise streicht über Euer Gesicht.>\n\nNur noch eines bleibt zu tun.\n\nPathaleon der Kalkulator überwacht die meisten Operationen seines Herrn. Er persönlich trägt die Verantwortung für einen Großteil des Leids, das in letzter Zeit über die Welt gekommen ist.\n\nIch möchte, dass Ihr ihn vernichtet.", sourceObjective = "A'dal hat Euch gebeten, Pathaleon den Kalkulator in der Mechanar der Festung der Stürme zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29659] = { id = 29659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Schatz", description = "Ich spüre, dass eines der Artefakte meines Volkes gestohlen wurde und im Behälter der Legion aufbewahrt wird.\n\nSie dürfen nicht entdecken, wie mächtig es ist. Würdet Ihr die Torwächter töten und es wiederbeschaffen? Ich wäre Euch sehr dankbar.", sourceObjective = "Beschafft für A'dal den Blendenden Zorn aus dem Behälter der Legion in der Mechanar der Festung der Stürme.", sourceObjectiveStatus = "unverified-source-field" }
quests[29660] = { id = 29660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Botanika", description = "Kael'thas und seinen Streitkräften ist es nicht gelungen, die vielen Kreaturen in der Botanika niederzuwerfen. Wir müssen versuchen, ihre Fehler wiedergutzumachen.\n\nDer erste Schritt ist die Eliminierung ihrer Streitkräfte, damit sie keinen weiteren Ärger mehr verursachen können.", sourceObjective = "A'dal möchte, dass Ihr Kommandantin Sarannis, Hochbotaniker Freywinn und Dorngrin den Hüter in der Botanika der Festung der Stürme tötet.", completion = "Die Kreaturen an diesem Ort hätten sie früher oder später auch ohne unser Eingreifen getötet. Wir haben zum Besten aller gehandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29667] = { id = 29667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausdünnung der Herde", description = "Anscheinend haben Kael'thas' Streitkräfte die Wesen der Botanika bis zur Unkenntlichkeit verändert. Ich will nicht, dass sie auf die Scherbenwelt losgelassen werden, wie so viele vor ihnen.\n\nEines dieser Wesen heißt Laj. Ihn würde ich gern untersuchen, denn er scheint irgendwie anders zu sein. Vielleicht können wir etwas von ihm lernen.", sourceObjective = "A'dal bittet Euch, 6 mutierte Fleischpeitscher und 6 mutierte Furchtkreischer zu töten und einen schnellentwickelnden Wedel von Laj in der Botanika der Festung der Stürme zu erbeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29669] = { id = 29669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine äußerst traurige Aufgabe", description = "Ich muss Euch leider mit einer äußerst traurigen Aufgabe betrauen.\n\nWarpzweig war einmal der Wächter der ganzen Botanika. Doch nun ist er unrein und muss beseitigt werden.", sourceObjective = "A'dal bittet Euch, Warpzweig in der Botanika in der Festung der Stürme zu töten.", completion = "Als er noch lebte, war er ein stattlicher Wächter. Wir werden ihn vermissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29674] = { id = 29674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbändige Dunkelheit", description = "<Ihr hört klagendes Geläut in Eurem Kopf.>\n\nWir haben die gefährlichsten Wesen, die uns auf unseren Reisen untergekommen sind, eingesperrt.\n\nZereketh ist ein mächtiger Herr der Leere. Wenn es ihm gelingt, in den Nethersturm zu entkommen, wird er die reichlich vorhandene Leerenenergie in sich aufsaugen.", sourceObjective = "A'dal hat Euch gebeten, Zereketh den Unabhängigen in der Arcatraz der Festung der Stürme zu töten.", completion = "Die Wesen der Leere sind von Natur aus chaotisch. Als Bestandteil des Universums sind sie notwendig, doch sie müssen stets unter der Kontrolle des Lichts stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29675] = { id = 29675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn und Verdammnis", description = "Zornseher Soccothrates und Dalliah die Verdammnisverkünderin sind zwei mächtige Agenten der Brennenden Legion. Sie haben damit begonnen, Dämonen um sich zu versammeln.\n\nNoch ist die Armee klein, aber Ihr dürft nicht zulassen, dasss sie größer wird, sonst wird die Arcatraz bald zu einem weiteren Stützpunkt der Legion werden.", sourceObjective = "A'dal bittet Euch, Zornseher Soccothrates und Dalliah die Verdammnisverkünderin in der Arcatraz der Festung der Stürme zu töten.", completion = "Der Legion geht es nur ums Verschlingen. Das Gleichgewicht der Kräfte interessiert sie nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29681] = { id = 29681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Hochsicherheitstrakt", description = "Herold Horizontiss stellt das größte Problem in der Arcatraz dar.\n\nEr hat Aufseher Mellichar korrumpiert und dafür gesorgt, dass er zahlreiche Gefangene entlässt. Es ist nur eine Frage der Zeit, bis auch der Herold selbst freigelassen wird.\n\n{name}, Ihr dürft einen Diener der Alten Götter nicht am Leben lassen!", sourceObjective = "A'dal hat Euch gebeten, Herold Horizontiss in der Arcatraz der Festung der Stürme zu töten.", completion = "Danke, {name}. Mit Euren Taten habt Ihr zahllose Tragödien verhindert.", sourceObjectiveStatus = "unverified-source-field" }
quests[29682] = { id = 29682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrasse der Magister", description = "Vor kurzem haben wir eine Expedition zur Terrasse der Magister geschickt, um die Streitkräfte der Legion aufzuhalten.\n\nAllerdings haben wir seitdem nichts mehr gehört, und ich befürchte das Schlimmste.\n\nWürdet Ihr dorthin gehen und versuchen, Exarch Larethor zu finden? Er leitet die Expedition.", sourceObjective = "Hauptmann Theris Morgenheim möchte, dass Ihr Exarch Larethor in der Terrasse der Magister findet.", completion = "Morgenheim hielt uns für tot? Ha!\n\nIch habe ihm keinen Bericht geschickt, weil wir noch nicht weiter als bis zu diesem Punkt gekommen sind.\n\nVielleicht können wir das ja mit Eurer Hilfe ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29684] = { id = 29684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgerissene Kommunikation", description = "Wir haben vor einiger Zeit einen Kontaktmann in der Terrasse der Magister eingeschleust, der für uns Informationen sammelt, aber der Kontakt zu ihm ist abgerissen.\n\nSein Wissen ist für unsere Mission essentiell.", sourceObjective = "Exarch Larethor in der Terrasse der Magister möchte, dass Ihr den Bluelfenspion Tyrith findet.", completion = "...kommt näher, {race}... Hört mir aufmerksam zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[29685] = { id = 29685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht totzukriegen", description = "Wie Ihr mittlerweile wisst, arbeiten die Streitkräfte der Legion unermüdlich daran, die Kräfte des Sonnenbrunnens zu manipulieren, um so ihre eigenen unholden Machenschaften zu verwirklichen.\n\nKael'thas ist aus der Asche der Niederlage auferstanden und ist einmal mehr zu ihrem Anführer geworden. Er muss aufgehalten werden.", sourceObjective = "Kalecgos hat Euch damit beauftragt, Kael'thas in der Terrasse der Magister zu bezwingen. Ihr sollt Euch mit Kaels Kopf bei Larethor in der Terrasse der Magister melden.", progress = "Nun ja, {class}, ich muss gestehen, dass ich mir nicht sicher war, ob ich Euch jemals wiedersehen würde.", completion = "<Larethor hört aufmerksam zu, als Ihr von Euren Heldentaten in der Terrasse der Magister berichtet.>\n\nMan wird Tyrith vermissen. Er war ein guter Mann. Dank Euch war sein Tod nicht umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[29686] = { id = 29686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine radikale Idee", description = "Wir können es uns nicht leisten, diesen Krieg zu verlieren. Ich möchte unsere Wachen stärken, damit mutige Männer und Frauen nicht sterben müssen.\n\nDer Legion ist ein mächtiges Elementarwesen in die Klauen gefallen. Seine Essenz könnte genau das sein, was wir brauchen.", sourceObjective = "Exarch Larethor auf der Terrasse der Magister bittet Euch, Vexallus zu töten und seine Essenz an Euch zu bringen.", progress = "Habt Ihr seine Essenz bekommen?", completion = "Hervorragend! Ich freue mich darauf, dieses Projekt meinen Vorgesetzten zu zeigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29687] = { id = 29687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Allianzen", description = "Die Legion arbeitet immer enger mit Kael'thas' Streitkräften zusammen. Das bereitet mir große Sorgen.\n\nSoweit wir wissen, sind vor allem Selin Feuerherz und Priesterin Delrissa mit der Vereinigung der beiden Armeen beschäftigt. Ihr müsst sie aufhalten.", sourceObjective = "Exarch Larethor in der Terrasse der Magister möchte, dass Ihr Selin Feuerherz und Priesterin Delrissa tötet.", completion = "Gut gemacht, Soldat. Ein Schritt nach dem anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29688] = { id = 29688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortführung der Kampagne", description = "Ich höre meistens zu, {class}. Ich höre zu, damit es der Kriegshäuptling nicht muss.\n\nIch habe gehört, wie es um unsere Kampagne gegen die Höllenfeuerzitadelle steht. Die Zeit zur Eroberung der Zerschmetterten Hallen, dem Machtzentrum der Höllenorcs, ist gekommen.\n\nSprecht mit Steingardist Stok'ton. Ihm unterstehen die Truppen dort.", sourceObjective = "Schattenjäger Ty'jin hat Euch gebeten, mit Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle zu sprechen.", completion = "Zieht den Kopf ein, sonst könnte er mit der falschen Seite eines Pfeils Bekanntschaft machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29689] = { id = 29689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortführung der Kampagne", description = "Die Zeit ist reif für einen letzten Schlag gegen die Höllenorcs.\n\nVorhutsspäher Chadwick erwartet Euch in den Zerschmetterten Hallen der Höllenfeuerzitadelle. Beeilt Euch, ihre Streitkräfte können jeden Moment die Ehrenfeste angreifen!", sourceObjective = "Truppenkommandant Danath Trollbann hat Euch gebeten, mit Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle zu sprechen.", completion = "Seid still! Wenn sie uns jetzt bemerken, werden sie uns überrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29691] = { id = 29691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ein Gebüsch!", description = "Wir benutzen Bluthibiskus für viele Zwecke.\n\nNatürlich kommt er nur im Tiefensumpf vor und zahlreiche Bewohner haben Gefallen daran gefunden.\n\nIch wäre Euch sehr dankbar, wenn Ihr mir etwas davon bringen würdet.", sourceObjective = "Sammelt 5 Bluthibisken und kehrt zu T'shu im Tiefensumpf zurück.", progress = "Habt Ihr Hibiskus gefunden?", completion = "Sehr gut, aber wir können immer etwas davon gebrauchen. Vielleicht verschlägt es Euch ja bald noch einmal in den Tiefensumpf?", sourceObjectiveStatus = "unverified-source-field" }
quests[29692] = { id = 29692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir ein weiteres Gebüsch!", progress = "Wir könnten noch mehr Bluthibiskus gebrauchen. Ständig sind wir auf der Suche danach.\n\nBringt sie mir in Fünferbündeln, dann werde ich mich erkenntlich zeigen.", completion = "Sehr gut, aber wir können immer etwas davon gebrauchen. Vielleicht verschlägt es Euch ja bald noch einmal in den Tiefensumpf?" }
quests[29734] = { id = 29734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Tiefenschmiede" }
quests[29735] = { id = 29735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Steinsiegel" }
quests[29736] = { id = 29736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Dunkelfeder" }
quests[29737] = { id = 29737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Feuerbart" }
quests[29739] = { id = 29739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Windsang" }
quests[29740] = { id = 29740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Immerschatten" }
quests[29741] = { id = 29741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Sekhemi" }
quests[29742] = { id = 29742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Menkhaf" }
quests[29760] = { id = 29760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grubenkämpfer", description = "Um ein meisterhafter Grubenkämpfer zu werden, muss man sicherlich noch mehr machen...\n\nVielleicht weiß Korgol Schädelquetscher, der die Todesgrube des Dunkelmond-Jahrmarkts auf dem Dunkelmond-Jahrmarkt leitet, mehr.", sourceObjective = "Sprecht mit Korgol Schädelquetscher auf dem Dunkelmond-Jahrmarkt.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[29763] = { id = 29763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt ihnen den Donner", description = "Die Vrykul kennen keine Angst. Sie scheinen sich sogar nach einem Tod in der Schlacht zu sehnen. Sie sind so zahlreich und werfen sich mit solcher Macht in den Kampf, dass wir nichts gegen sie ausrichten können.\n\nEs gibt jedoch einen, den sie verehren. Sein Name ist Ingvar. Wenn Ihr ihn töten könntet, würde das ihre Kampfeslust deutlich bremsen.", sourceObjective = "Verteidiger Mordun hat Euch gebeten, ihm den Kopf von Ingvar dem Brandschatzer zu bringen.", progress = "Schön zu sehen, dass es Euch gut geht, {name}.\n\nWeitere Verluste könnten wir nicht verkraften.", completion = "Hervorragend!\n\nDas könnte der Durchbruch sein, auf den wir gehofft haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29764] = { id = 29764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrüstung", description = "Ihr könnt mir glauben, <Kamerad/Fräulein>, diese Vrykulwaffen sind verdammt unangenehm! Trügerisch gut ausbalanciert, brutal scharf - absolut tödlich.\n\nKlaut mir ein paar davon, bevor sie gegen uns eingesetzt werden.", sourceObjective = "Verteidiger Mordun möchte, dass Ihr 5 Waffen der Vrykul stehlt.", progress = "Habt Ihr ein paar Äxte der Vrykul geklaut?", completion = "<Mordun pfeift.>\n\nSeht Euch die nur mal an! Unglaublich.\n\nIch hatte eigentlich erwartet, dass diese Steinzeitmenschen mit Knüppeln herumfuchteln und Steine werfen.\n\nLeider nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[29801] = { id = 29801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewährungsprobe", description = "Hallo, {name}! Im Schwarm hat sich herumgesprochen, dass Ihr ziemlich... wie soll ich sagen... geschickte Finger habt.\n\nWir könnten jemand mit Euren Fähigkeiten für eine äußerst delikate Aufgabe gebrauchen. Bevor ich fortfahre, muss ich wissen, ob Ihr <der richtige Mann/die richtige Frau> für diese Angelegenheit seid. Wenn Euch der Krieg zum Auge der Ewigkeit führt, möchte ich, dass Ihr Hagara die Sturmbinderin bestehlt und Ihr den Entschlüsselungsring eines Kryptomanten abnehmt. Wollt Ihr Euch dieser Aufgabe stellen?", sourceObjective = "Bestehlt Hagara die Sturmbinderin im Auge der Ewigkeit in der Drachenseeleninstanz und beschafft Euch so einen Entschlüsselungsring des Kryptomanten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29803] = { id = 29803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ohren des Lichkönigs", description = "Im Fjord dient Prinz Keleseth als Arthas' Augen und Ohren.\n\nDas gefällt mir kein bisschen!\n\nMacht Arthas hier taub und blind. Damit erweist Ihr der Welt einen Gefallen.", sourceObjective = "Verteidiger Mordun in Burg Utgarde möchte, dass Ihr Prinz Keleseth tötet.", completion = "Ich wette, das hat dieses Blassgesicht gespürt!\n\nEin weiterer Schritt auf dem Weg zur Abrechnung, Arthas!", sourceObjectiveStatus = "unverified-source-field" }
quests[29807] = { id = 29807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod dem Verräterkönig", description = "Anub'arak der Verräterkönig ist im einst stolzen unterirdischen Azjol-Nerub zuhause.\n\nEr hat unsere Heimat in den erbärmlichen Haufen Dreck verwandelt, den wir heute sehen. Er herrscht über eine Armee untoter Neruber, die dem Lichkönig die Treue geschworen haben.\n\nSetzt der Herrschaft des Verräterkönigs ein Ende.", sourceObjective = "Pionier A'zak in Azjol-Nerub hat Euch aufgetragen, Anub'arak zu besiegen. Kehrt danach mit Anub'araks zerbrochenem Panzer zu A'zak zurück.", progress = "Ist es getan, {class}? Hat der Verräterkönig endlich sein Leben ausgehaucht?", completion = "<A'zaks Augen beginnen durchdringend zu leuchten, als er den Panzer anstarrt.>\n\nEs ist VOLLBRACHT!\n\n{race}! Euer Name wird in die Annalen meines Volkes aufgenommen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29808] = { id = 29808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst die Eier nicht!", description = "In ganz Azjol-Nerub liegen Eier, die von den Nerubern der Geißel gehegt und gepflegt werden. Die Jungen werden bald schlüpfen um geschlachtet und als Untote wiedererweckt zu werden.\n\nDiese Eier wurden mit fauler Magie verunreinigt. Wir müssen sie unbedingt vernichten.", sourceObjective = "Pionier A'zak in Azjol-Nerub möchte, dass Ihr 6 Eier der Geißelneruber zerstört.", completion = "Keine Sorge, {race}.\n\nWir haben die meisten unserer Eier gut in Azjol-Nerub versteckt. Sie haben nur ein paar gefunden.\n\nUnser mächtiges Königreich wird wieder auferstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29811] = { id = 29811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Talisman des Torwächters", description = "Krik'thir, Wächter der Tore von Azjol-Nerub, war kein Verräter.\n\nEr fiel im Krieg der Spinne, als er unsere Heimat gegen die Geißel verteidigte.\n\nWie es seiner Stellung gebührte, besaß er den Schlüssel zum verborgenen Reich. Ich möchte, dass Ihr ihn bergt, damit er seinem Volk überbracht werden kann.", sourceObjective = "Pionier A'zak in Azjol-Nerub möchte, dass Ihr den Talisman des Torwächters von Krik'thir dem Torwächter erbeutet.", progress = "Wurde Krik'thirs Geist vom Fluch des Untodes befreit? Was ist mit dem Talisman?", completion = "Ich hatte es geahnt.\n\nEin Großteil des Reiches ist seit Krik'thirs letztem Kampf verschlossen geblieben. Vielleicht hat mein Volk die Tiefen bereits gesichert und wartet nur auf seine Befreiung. Vielleicht sind es jedoch auch die Gesichtslosen, die hinter verschlossenen Türen lauern.\n\nWir werden es irgendwann erfahren. Zuerst muss jedoch der freigelegte obere Teil von Azjol-Nerub von Arthas' Schmutz gesäubert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29820] = { id = 29820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein in den Nexus", description = "Ich habe Kriegsmagierin Kaitlyn in den Nexus geschickt, damit sie Malygos' chaotisches Reich untersucht, aber sie hat sich seit Tagen nicht gemeldet.\n\nKönntet Ihr dorthin gehen und sie unterstützen? Sie könnte sicherlich Hilfe gebrauchen, wenn die Drachen sie nicht schon gefressen haben.", sourceObjective = "Erzmagier Berinand hat Euch gebeten, mit Kriegsmagierin Kaitlyn im Nexus zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29825] = { id = 29825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht länger ein Schüler", description = "Einst nannte ich Urahne Nadox meinen Lehrer.\n\nDas änderte sich für immer, als ich zusehen musste, wie er, ein Diener der Verdammten, meine Freunde und meine Familie umbrachte.\n\nFindet ihn in den Tiefen und sorgt dafür, dass er für seine Verbrechen bezahlt.", sourceObjective = "Seher Ixit in Ahn'kahet hat Euch gebeten, Urahne Nadox zu töten.", progress = "Ist der mächtige Nadox endlich tot?", completion = "Ich hoffe, dass ich nun an Nadox' Stelle treten und mein Volk anführen kann.\n\nDas Reich von Azjol-Nerub wird Großes vollbringen, {race}...", sourceObjectiveStatus = "unverified-source-field" }
quests[29826] = { id = 29826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung von Ahn'kahet", description = "Prinz Taldaram und seine Geißelarmee benutzen die gleichen Barrieren, hinter denen wir einst unser Reich verbargen, um sich vor den Einheimischen der eisigen Tiefen zu schützen.\n\nDeaktiviert die Barrieren und tötet die Geißelsoldaten, die sie bewachen. Meine Streitkräfte werden zusammen mit den Einheimischen den Rest erledigen.", sourceObjective = "Seher Ixit in Ahn'kahet möchte, dass Ihr 3 Augen von Taldaram, einen Knochenschinder und Prinz Taldaram tötet.", completion = "Hervorragend.\n\n<Ihr hört einige klickende Geräusche.>\n\nUnd nun zu unserem anderen Feind...", sourceObjectiveStatus = "unverified-source-field" }
quests[29828] = { id = 29828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Alptraum der Geißel", description = "Ein flüchtender Drakkaritroll hat mir von einem großen Raptorkönig namens Dred erzählt, der gegen die Seuche immun ist.\n\nFindet diesen König Dred und bringt mir einen seiner Zähne. Vielleicht kann ich daraus eine Waffe herstellen.", sourceObjective = "Kurzel in der Feste Drak'Tharon möchte, dass Ihr König Dred tötet und ihr seinen Zahn bringt.", progress = "Gibt es diese gewaltige Bestie wirklich?", completion = "<Kurzels Augen weiten sich.>\n\nBoah! Der ist ja riesig!", sourceObjectiveStatus = "unverified-source-field" }
quests[29829] = { id = 29829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskretion ist der Schlüssel", description = "Hört mir zu, {race}.\n\nMir wurde soeben mitgeteilt, dass sich in der Violetten Festung ein Zwischenfall ereignet hat. Es scheint, als würde der blaue Drachenschwarm eine groß angelegte Invasion Dalarans vorbereiten!\n\nIch möchte, dass Ihr Euch umgehend zum Gefängnis begebt und mit Leutnant Sinclari sprecht. Sie wird Euch alles erklären.\n\nDoch das ist nicht alles. Ihr müsst äußerst diskret vorgehen. Wir dürfen die Bürger Dalarans nicht verunsichern, wenn es sich vermeiden lässt. Habe ich mich klar ausgedrückt?\n\nGut. Dann geht jetzt.", sourceObjective = "Rhonin möchte, dass Ihr zur Violetten Festung in Dalaran geht und mit Leutnant Sinclari sprecht.", completion = "Keinen Augenblick zu früh.\n\nSeid Ihr bereit, Dalaran zu verteidigen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[29830] = { id = 29830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung", description = "Meine Streitkräfte liegen am Boden, aber Malygos' Angreifer stürmen immer weiter auf uns ein.\n\nIhr müsst sie aufhalten, bis ihre Anführerin Cyanigosa auftaucht. Nur ihr Tod wird die Invasion beenden und Dalaran retten.\n\nSprecht mich an, wenn Ihr bereit seid.", sourceObjective = "Leutnant Sinclari in der Violetten Festung möchte, dass Ihr die Invasion der blauen Drachen aufhaltet. Sprecht mit ihr, wenn Cyanigosa geschlagen ist.", progress = "Ist es vorbei? Konntet Ihr dem Angriff standhalten?", completion = "Danke, mein Held!\n\nDank Eures Mutes konnte Dalaran einen weiteren Tag überstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29833] = { id = 29833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Der Prophet von Akali mag diese Welt zwar nicht mehr belästigen, doch es gibt noch immer Arbeit zu tun.\n\nAkalis Blut - ein Großteil davon - hat jemand anderem Macht verliehen und es ist dieser jemand, von dem die eigentliche Gefahr ausgeht.\n\nSchnell, {name}, macht Euch auf den Weg nach Gundrak und sprecht mit Tol'mar. Er wird Euch diesbezüglich weitere Anweisungen geben können.", sourceObjective = "Har'koa möchte, dass Ihr mit Tol'mar in Gundrak sprecht.", completion = "Hör zu, Mann. Die Arbeit, die hier erledigt werden muss, is' gefährlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[29834] = { id = 29834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah muss bezahlen", description = "War das schlimmste, was ich je gesehen hab', Mann. Der große Akali - vor meinen Augen getötet. Furchtbar...\n\nIch bin nur hier, um zu beobachten, aber so was geht nich'! Gal'darah un' seine Anhänger müssen dafür bezahlen!\n\nRäche Akalis Tod, Mann. Muss sein.", sourceObjective = "Tol'mar möchte, dass Ihr Slad'ran, Moorabi und Gal'darah in Gundrak tötet.", completion = "Du hast es getan?! Sie sind hin?\n\nHier, Mann. Das Geschenk is' für dich, weil du den Eisigen Weiten Gerechtigkeit gebracht has'.", sourceObjectiveStatus = "unverified-source-field" }
quests[29835] = { id = 29835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah muss bezahlen", description = "Der mächtige Akali is' tot, {race}.\n\nMeine Rolle im Leben ist es, Dinge aufzuzeichnen, nich' zu kämpfen. Aber das geht nicht! Gal'darah und seine Anhänger müssen bezahlen!\n\nRäche Akalis Tod, Mann. Muss sein.", sourceObjective = "Chronistin Bah'Kini möchte, dass Ihr Slad'ran, Moorabi und Gal'darah in Gundrak tötet.", completion = "Du hast es getan?\n\nDamit hast du meine Erwartungen voll übertroffen, Mann. Das Geschenk is' für dich, weil du den Eisigen Weiten Gerechtigkeit gebracht has'.", sourceObjectiveStatus = "unverified-source-field" }
quests[29836] = { id = 29836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ma' nachsehen", description = "Unten aus Gundrak waren fürchterliche Geräusche zu hören. In letzter Zeit sind sie lauter geworden und auch häufiger zu hören.\n\nMeine langjährige Schülerin konnte von ihrem Posten westlich von Gundrak aus die Ereignisse erfassen. Hättet Ihr vielleicht Zeit, bei Ihr nachzusehen, was los ist?", sourceObjective = "To'kini möchte, dass Ihr mit Bah'Kini in Gundrak sprecht.", completion = "To'kini is' mein feiger Vater - er traut sich nicht so nahe an Gundrak heran... deshalb hat er mich geschickt!\n\nHier gibt's soviel Trollgeschichte. Wir dürf'n nich' zulassen, dass Gal'darah un' seine irren Anhänger sie auf ewig vor uns verstecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[29838] = { id = 29838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartig", description = "Auf'n ersten Blick denkt ma', die Geschichte kenn' ich schon: Trolle zapf'n verbotene Energien an, weil sie die Wesen vernicht'n, die sie eigentlich anbeten sollt'n.\n\nWenn's stimmt, was ich so hör', dann haben sie 'nen besonderen Golem - einen, der anders is' als alle and'ren vor ihm!\n\nBring mir'n Stück von dem Golem zum Untersuchen, Mann.", sourceObjective = "Chronistin Bah'Kini möchte, dass Ihr ein Stück des Kolosses der Drakkari in Gundrak erbeutet.", progress = "Hast du mir ein Stück dieses Golems gebracht, Mann?", completion = "Ahh, ja Mann! Das ist es, wonach ich gesucht habe.\n\nHier, bitte schön - nimm dir was Schönes für den Ärger, den du hattest.", sourceObjectiveStatus = "unverified-source-field" }
quests[29839] = { id = 29839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartig", description = "Dem ganz'n Ärger hätte man aus'm Weg gehen können, wenn die Drakkari die Götter angebetet, anstatt umgebracht hätt'n.\n\nIch hab gehört, dass sie 'nen besonderen Golem haben, einen, in dem verbotene Energien stecken.\n\nBring mir ein Stück von dem Golem, Mann, damit wir von uns'ren Brüdern und Schwestern lernen können.", sourceObjective = "Tol'mar möchte, dass Ihr ein Stück des Kolosses der Drakkari in Gundrak erbeutet.", progress = "Hast du den Golem gefunden, Mann? Der muss da irgendwo sein.", completion = "Unglaublich! Sowas hab' ich noch nie geseh'n.\n\nGute Arbeit, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[29840] = { id = 29840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Gundrak is' nich' mehr zu rett'n, Mann. Du weißt, dass ich Recht habe.\n\nWenn du den Mut dazu hast, such nach Geschichtstafeln, in denen steht, wieso das Reich der Drakkari gefall'n is'.\n\nVielleicht könn'n wir's eines Tages wieder aufbau'n.", sourceObjective = "Chronistin Bah'Kini in Gundrak möchte, dass Ihr 6 Geschichtstafeln der Drakkari sammelt.", progress = "Haste die Geschichtstafeln der Drakkari gefund'n, Mann?", completion = "Bin dir echt dankbar dafür, Mann.\n\nDie werd'n uns 'ne große Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29844] = { id = 29844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Das Land der Eistrolle is' nur noch'n Schatten seiner selbst.\n\nWenn du genug Mut aufbringst, dann such doch mal nach Geschichtstafeln, Mann. Da steht drin, wieso das Reich der Drakkari untergegang'n ist.\n\nEines Tages werd'n wir das Land vielleicht an 'ne neue Generation Frosttrolle weitergeb'n können.", sourceObjective = "Tol'mar in Gundrak möchte, dass Ihr 6 Geschichtstafeln der Drakkari sammelt.", progress = "Haste die Geschichtstafeln der Drakkari gefund'n, Mann?", completion = "Die Reiche von uns Trollen werd'n schon länger gespalten als es die and'ren Völker gibt, Mann.\n\nWir steh'n immer wieder aus den Ruinen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[29848] = { id = 29848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Behüterin", description = "Ich würde mein Leben mit Freuden für die Schöpfer oder ihre Wesen hingeben.\n\nSeit Lokens Verrat scheint es mir jedoch, als habe sich ganz Ulduar gegen die Welt verschworen. Vor allem die Maid der Trauer leidet entsetzlich unter ihren neuen Befehlen.\n\nBitte schenkt ihr Frieden und bringt mir eine ihrer Tränen.", sourceObjective = "Kaldir Eisenbann in den Hallen des Steins möchte, dass Ihr der Maid der Trauer Frieden schenkt und eine Kristallträne der Trauer beschafft.", progress = "Ich wünschte, es gäbe einen anderen Weg, aber nur der Tod kann die Maid jetzt noch erlösen.", completion = "<Kaldir starrt einen Moment schweigend in den Kristall.>\n\nKein Wesen hat das Leid je so gespürt wie die Maid der Trauer.\n\nDaran sollten wir denken, während wir unseren Kampf gegen Loken fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29850] = { id = 29850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrupte Konstrukte", description = "Die Eisenzwerge haben damit begonnen, gewaltige Steinkonstrukte zu erschaffen, die sie, so fürchte ich, bald als mächtige Waffen einsetzen werden.\n\nIhr müsst unbedingt ihren Aufseher Krystallus und die dunklen Runenriesen, die bereits in den Hallen aufgetaucht sind, besiegen. Beeilt Euch, bevor es zu spät ist!", sourceObjective = "Kaldir Eisenbann in den Hallen des Steins möchte, dass Ihr Krystallus und 3 dunkle Runenriesen tötet.", completion = "Gut gemacht, {race}.\n\nJede Waffe, die wir Loken abnehmen können, hilft unserem eigenen Feldzug.", sourceObjectiveStatus = "unverified-source-field" }
quests[29851] = { id = 29851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Turniers", description = "Dank dieses Turniers kommen wir unserer letzten Konfrontation mit dem Lichkönig immer näher.\n\n{name}, kämpft tapfer und ehrenhaft. Die Kämpfer hier haben sich hier zu unser aller Wohl versammelt.\n\nGemeinsam werden wir Arthas aufhalten!", sourceObjective = "Hochlord Tirion Fordring hat Euch beauftragt, die Prüfung des Champions zu vollenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29860] = { id = 29860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegensätze", description = "Ich werde offen mit Euch sprechen, <kleiner/kleine:r> {race}. Mein Volk ist nicht mehr das gleiche, seit unsere Verbindung zu Thorim abgerissen ist.\n\nVolkhan wird nicht ruhen, bis er oder wir nicht mehr existieren. Wir wollen nur Frieden, doch es scheint, als läge unsere einzige Hoffnung im Krieg.", sourceObjective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr Volkhan besiegt.", completion = "Volkhan wird mein Volk nicht mehr in seinen Träumen heimsuchen.\n\nMacht weiter wie bisher, kleiner {race}. Irgendwann wird mein Volk Thorim schon vergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29861] = { id = 29861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit allen Mitteln!", description = "Loken wird fallen, egal, wie.\n\nDie Ehre und der Ruhm seiner Niederlage soll Euch gebühren.\n\nKehrt zu mir mit seiner gespaltenen Zunge zurück und verdient Euch meinen ewigen Dank.", sourceObjective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr Loken besiegt. Dann sollt Ihr mit Lokens Zunge zu Sturmbote Eljrrin zurückkehren.", progress = "Habt Ihr Gerechtigkeit über Loken gebracht?", completion = "Dieser widerliche Wurm ist tot?\n\nIhr seid wahrhaft ein Segen für mein Volk, kleiner {race}. Bitte nehmt dieses Geschenk als Anerkennung Eurer loyalen Freundschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29862] = { id = 29862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg frei machen", description = "Lokens Streitkräfte bereiten sich auf den Krieg vor. Sie rechnen allerdings nicht damit, selbst angegriffen zu werden.\n\nWir müssen rasch zuschlagen. Vernichtet General Bjarngrim und seine Armee, bevor sie alles Leben auf Azeroth gefährden!", sourceObjective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr 3 sturmgeschmiedete Heiler, 3 sturmgeschmiedete Taktiker und General Bjarngrim tötet.", completion = "Nur wenige außer uns werden je davon erfahren, aber Ihr habt an diesem Tag die Welt gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29863] = { id = 29863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmbote Eljrrin", description = "Ich habe einen Abgesandten in die Hallen der Blitze geschickt, um Loken zu bedrängen.\n\nEr könnte zweifellos Hilfe gebrauchen, wenn man die Stärke von Lokens Armeen bedenkt. Unterstützt ihn so gut Ihr könnt, damit wir den Verräter endlich besiegen können.", sourceObjective = "König Jokkum möchte, dass Ihr die Hallen der Blitze betretet und mit Sturmbote Eljrrin sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29864] = { id = 29864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzel des Übels", description = "Wir tun alles, um die Verluste, die uns die Kriegsmaschinerie der Geißel zufügt, zu minimieren.\n\nDie Vrykul gefährden diese Mission, indem sie sich willentlich den Truppen des Lichkönigs anschließen.\n\nBitte, <edler Held/edle Heldin>, besiegt ihre spirituelle Anführerin Svala, bevor sie ihr Volk in die ewigen Schatten führt!", sourceObjective = "Argentumbeichtpatin Blondlocke möchte, dass Ihr Svala Grabesleid tötet.", completion = "Jeder Soldat, den wir der Geißel vorenthalten, bedeutet mehr als nur ein gerettetes Leben.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[30110] = { id = 30110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Finder (1st)" }
quests[30111] = { id = 30111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Finder (Nth)" }
quests[30112] = { id = 30112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Rechnung begleichen", description = "Utgardes Horden organisieren sich mit Hilfe der Ratschläge von Keleseth, dem San'layn-Botschafter der Geißel.\n\nWir können es nicht länger zulassen, dass die Vrykul von diesem Rat profitieren. Bringt ihn zum Schweigen.", sourceObjective = "Dunkelläuferin Marrah möchte, dass Ihr Prinz Keleseth in Burg Utgarde tötet.", completion = "Rache ist süß. Und dies ist nur ein Vorgeschmack dessen, was Arthas noch bevorsteht.\n\nEr wird früh genug das bekommen, was er verdient hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[30120] = { id = 30120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Drak'Tharons", description = "Bald wird Drak'Tharon von den verdorb'nen Untoten gereinigt und wieder ihrer ursprünglichen noblen Aufgabe unterstellt werd'n. Als Belohnung für deine Hilfe werd'n dir die wertvollsten Schätze der Feste zur Verfügung steh'n, Mann!\n\nSobald du ihre Spitze erreicht hast, musst du mich beschwör'n, und ich führ' das Ritual durch.\n\nAber mich zu ruf'n, Mann, wird einiges kost'n. Du musst das Mojo von den Überlebenden sammeln.", sourceObjective = "Drakuru möchte, dass Ihr Drakurus Elixier an seinem Kohlenbecken innerhalb Drak'Tharons benutzt. Um das Elixier dort benutzen zu können, benötigt Ihr 5 Ausdauermojos.\n\nBereitgestellter Gegenstand:", completion = "Wir ham' großes geleistet, Mann! Un' das is' nur der Anfang…\n\nSuch mich in Zul'Drak auf, wenn die Zeit reif is'.\n\nEs gibt 'nen Krieg zu gewinnen, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[30173] = { id = 30173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frontschweine" }
quests[30177] = { id = 30177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher zufälliger, heroischer Dungeon (Erster) (Cataclysm)" }
quests[30538] = { id = 30538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaß für die Kleinen", description = "Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.\n\nIch vergrabe Artefakte und Fossilien im Sandkasten hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.\n\nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?", sourceObjective = "Bringt 15 mit Archäologie aufgespürte Fossilienfragmente zu Professor Thaddeus Paleo beim Dunkelmond-Jahrmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63448] = { id = 63448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Deluxelieferung", sourceObjective = "Grüße, {name}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63450] = { id = 63450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Deluxelieferung", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnungen im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diese Gegenstände jemals verlieren, kommt zu mir zurück, und ich ersetze sie Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[63767] = { id = 63767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtel in der Kugel", sourceObjective = "Grüße, {class}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch etwas auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals diesen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63768] = { id = 63768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtel in der Kugel", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnung im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diesen Gegenstand jemals verlieren, kommt zu mir zurück, und ich ersetze ihn Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[63770] = { id = 63770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderer Dank" }
quests[63865] = { id = 63865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderer Dank", sourceObjective = "Grüße, {name},\n\nHier ist ein besonderes Geschenk für Euch als passionierten Sammler! Wir möchten Euch diesen kleinen aber aufgeweckten Freund überreichen. Möge er Euch zu neuen Abenteuern auf der anderen Seite des Dunklen Portals in der Scherbenwelt führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[63866] = { id = 63866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beherrschung des Lichts", description = "Nehmt dieses Gefäß, {name}. Seine Magie wird es Euch erlauben, die Macht dieser Kreatur an Euch zu nehmen. Mit ihr werdet Ihr in der Lage sein, Euren gefallenen Kameraden wieder zum Leben zu erwecken.\n\nManche werden sagen, dass unser Handeln falsch ist, aber vieles von dem, was uns widerfahren ist, ist auch falsch. Sollen wir denn solch ein Geschenk wegwerfen?\n\nSie behalten ihre Kritik für sich, wenn unsere Macht die weitere Zerstörung Silbermonds verhindert. Doch sobald sie sich in teuer erkaufter Sicherheit ihren magischen Süchten hingeben können, erheben sie ihre Einsprüche.", sourceObjective = "Füllt das schimmernde Gefäß bei M'uru und kehrt anschließend zu Ritterfürst Heldenblut in Silbermond zurück.", progress = "Habt Ihr schon mit Magister Astalor Blutschwur gesprochen?", completion = "Gut gemacht, {name}. Die vom Licht gewährten Kräfte sind niemals auf 'natürlichem' Wege zu den Blutrittern gekommen, aber wir sind nicht so willensschwach, um unseren Weg von der Natur diktieren zu lassen.\n\nUnsere Beherrschung des Arkanen hat uns einen Pfad durch diese rauen Zeiten eröffnet. Die Kräfte fließen nicht mehr frei in diesen Hallen, doch sie sind da, für die hartnäckigen und willensstarken. Nur wenige sind heutzutage mutig genug, oder verfügen über die Begabung, sie zu meistern, aber ich weiß, dass Ihr den Orden nicht enttäuschen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[64028] = { id = 64028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Sturmwind, Hauptstadt der Allianz!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Sturmwind, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[64031] = { id = 64031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", progress = "Ich habe ein Überlebenspaket für Eure Abenteuer zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Macht guten Gebrauch davon.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[64034] = { id = 64034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64035] = { id = 64035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, {name}!" }
quests[64037] = { id = 64037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Östliche Pestländer", description = "Auf Anweisung von Hochlord Bolvar Fordragon ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Lord Bartholomäus in der Kapelle des Hoffnungsvollen Lichts zu melden.\n\nDie Argentumdämmerung benötigt Eure Hilfe dabei, die Östlichen Pestländer von der Geißel zu befreien.\n\nUm in die Östlichen Pestländer zu gelangen, sprecht mit dem Greifenmeister Dungar Trinkfest. Seine Greifen können Euch schneller als jedes Pferd dorthin bringen.\n\nFür Ruhm und Ehre der Allianz!", sourceObjective = "Reist in die Östlichen Pestländer und macht Leonidas Bartholomäus ausfindig. Er wartet in der Kapelle des Hoffnungsvollen Lichts.", completion = "Vielleicht könnt Ihr helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64038] = { id = 64038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dunkle Portal", description = "Es existiert ein höllisches Tor, das jahrelang geruht hat. Jetzt ruht es nicht mehr.\n\nAuf Anweisung von Hochlord Bolvar Fordragon ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend in den Verwüsteten Landen zu melden. Sprecht mit Dungar Trinkfest, um einen Flug dorthin zu arrangieren.\n\nSobald Ihr angekommen seid, meldet Euch umgehend bei Wachkommandant Reldorn Netherschwund. Er erwartet Euch vor dem Dunklen Portal...", sourceObjective = "Macht Wachkommandant Reldorn Netherschwund in den Verwüsteten Landen ausfindig. Er erwartet Eure Ankunft vor dem Dunklen Portal.", completion = "Willkommen zum Alptraum!", sourceObjectiveStatus = "unverified-source-field" }
quests[64046] = { id = 64046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Orgrimmar, Hauptstadt der Horde!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Orgrimmar, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[64047] = { id = 64047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Donnerfels, Hauptstadt der Tauren!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Donnerfels, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung?", sourceObjectiveStatus = "unverified-source-field" }
quests[64048] = { id = 64048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[64049] = { id = 64049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[64050] = { id = 64050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Orgrimmar, Donnerfels oder der Unterstadt Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64051] = { id = 64051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Donnerfels, Orgrimmar oder der Unterstadt Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64052] = { id = 64052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, {name}!" }
quests[64053] = { id = 64053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid fast bereit für den Kampf, {name}!" }
quests[64063] = { id = 64063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dunkle Portal", description = "Es existiert ein höllisches Tor, das jahrelang geruht hat. Jetzt ruht es nicht mehr.\n\nAlle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich in den Verwüsteten Landen zu melden. Begebt Euch zum Zeppelinmeister vor den Toren Orgrimmars und fliegt zum Basislager Grom'gol. Sprecht dort mit Thysta, um einen Flug nach Steinard zu erhalten.\n\nMeldet Euch umgehend bei Kriegsherr Dar'toon. Er erwartet Euch vor dem Dunklen Portal...", sourceObjective = "Macht Kriegsherr Dar'toon ausfindig. Er erwartet Eure Ankunft vor dem Dunklen Portal.", completion = "Willkommen zum Alptraum!", sourceObjectiveStatus = "unverified-source-field" }
quests[64064] = { id = 64064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Östliche Pestländer", description = "Alle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich bei Leonidas Bartholomäus in der Kapelle des Hoffnungsvollen Lichts zu melden.\n\nDie Argentumdämmerung hat ihre Position in den Pestländern gefestigt und benötigt Eure Hilfe, um ihre Siege zu konsolidieren.\n\nBesucht Zeppelinmeister Frezza vor dem Haupttor und reist zur Unterstadt. Reist von dort aus zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.\n\nDas Schicksal wartet!", sourceObjective = "Reist in die Östlichen Pestländer und macht Leonidas Bartholomäus ausfindig. Er erwartet Eure Ankunft in der Kapelle des Hoffnungsvollen Lichts.", completion = "Vielleicht könnt Ihr helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64128] = { id = 64128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Östliche Pestländer", description = "Alle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich bei Leonidas Bartholomäus in der Kapelle des Hoffnungsvollen Lichts zu melden.\n\nDie Argentumdämmerung hat ihre Position in den Pestländern gefestigt und benötigt Eure Hilfe, um ihre Siege zu konsolidieren.\n\nSprecht mit Tal, unserem Windreitermeister, um nach Orgrimmar zu fliegen. Von dort bringt Euch Zeppelinmeister Frezza vor dem Haupttor zur Unterstadt. Ihr könnt von dort aus in die Östlichen Pestländer gelangen.\n\nDas Schicksal wartet!", sourceObjective = "Reist in die Östlichen Pestländer und macht Leonidas Bartholomäus ausfindig. Er wartet in der Kapelle des Hoffnungsvollen Lichts.", completion = "Vielleicht könnt Ihr helfen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64139] = { id = 64139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vorladung von Lady Liadrin", description = "Eure Aufopferung für den Orden und Euer rascher Aufstieg innerhalb seiner Ränge sind nicht unbeachtet geblieben. Tatsächlich erbittet Lady Liadrin Eure Gegenwart.\n\nDas ist eine seltene Ehre, {name}. Normalerweise überlässt Lady Liadrin mir die Verwaltung des Ordens und das damit verbundene Tagesgeschäft, doch scheint sie ein besonderes Interesse an Euch zu haben. Wartet nicht zu lange, {name}.", sourceObjective = "Sprecht mit Lady Liadrin in Silbermond.", completion = "Wir werden den Grund Eures Besuchs noch früh genug besprechen. Doch zunächst muss ich feststellen, dass mich Eure bisherigen Leistungen und Euer Geschick in der Beherrschung des Lichts sehr beeindruckt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[64140] = { id = 64140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Meisters", description = "Innerhalb unseres Ordens existiert ein eingeschworener Zirkel von Eliterittern. Die Mitglieder des Zirkels repräsentieren die Hingebungsvollsten, Fähigsten und Vertrauenswürdigsten aller Blutritter, allesamt handverlesen und vereidigt durch die Ordensführung. Diese Meister sind leicht an ihrem thalassischen Schlachtross zu erkennen.\n\nJeder Kandidat, der sich um die Aufnahme in diese erlesene Gemeinschaft bewirbt, benötigt einen Fürsprecher aus den Reihen des Zirkels und muss seine Hingabe für die zentralen Grundsätze des Ordens unter Beweis stellen.\n\nIch habe beschlossen, Euch als Fürsprecher zur Seite zu stehen, sollte es Euer Wunsch sein, in die Reihen der Meister der Blutritter aufgenommen zu werden.", sourceObjective = "Sprecht erneut mit Lady Liadrin, um ihr Angebot, für Euch zu sprechen, anzunehmen.", completion = "Dass Ihr Euch entschlossen habt, mein Angebot zu akzeptieren, spricht für Euch, {name}. Ich wünsche Euch viel Glück, bei den von mir festzulegenden Prüfungen, doch bin ich zuversichtlich, dass Ihr sie alle meistern werdet.\n\nIch werde Euch die Aufgaben in der Reihenfolge ihrer Schwierigkeit, von der Leichtesten bis zur Schwersten, erteilen. Wir können beginnen, sobald Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[64141] = { id = 64141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Geste der Hingabe", description = "Die Loyalität eines Blutritters endet nicht an der Spitze seiner Klinge, {name}. Der Orden verlangt mehr von seinen Mitgliedern, als schiere Ausbildung und Kampf. Ein wahrer Ritter trägt zu allen Aktivitäten des Ordens etwas bei, selbst zu denen, die nicht offensichtlich Ruhm verheißen.\n\nDiese erste Aufgabe fordert weder Eure Kampfeskunst, noch ist sie besonders ruhmreich, doch ohne solche Tätigkeiten würde der Orden auseinander fallen. Ich werde Euch eine Liste mit Gegenständen geben, die Magister Astalor Blutschwurs Männer benötigen, um uns mit Lichtenergie für unsere Magie zu versorgen.", sourceObjective = "Bringt 40 Einheiten Runenstoff, 6 Arkanitbarren, 10 Einheiten Sonnengras, 5 Dunkelrunen und 150 Goldstücke zu Lady Liadrin in Silbermond.", progress = "Habt Ihr die von Magister Astalor benötigten Materialien bei Euch?", completion = "Hervorragend. Es sieht so aus, als sei alles da.\n\nKeine Sorge, im Laufe Eurer nächsten Aufgabe habt Ihr noch oft genug die Möglichkeit, von Eurer Waffe Gebrauch zu machen, versprochen!\n\nIch werde einen Initianden losschicken, um alles zu Magister Astalor zu bringen. Es wäre Verschwendung, Euch mit einem solch trivialen Botengang zu betrauen, wenn wesentlich wichtigere Dinge auf ihre Erledigung warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64142] = { id = 64142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Demonstration Eurer Loyalität", description = "Wir Blutritter haben geschworen, Quel'Thalas zu verteidigen, {name}. Dies ist ein zentraler Teil unserer Ausbildung. Unsere Feinde sind wild und unbeugsam. Einzig unsere Anstrengungen und die Unterstützung unserer Verbündeten sind der Garant für die Freiheit eines jeden Bürgers von Silbermond.\n\nIch habe einige beunruhigende Berichte über die verstärkte Präsenz der Geißel, südöstlich unserer Grenze zu den östlichen Pestländern, erhalten. Eine Kompanie Belagerungsingenieure der Geißel, mitsamt Belagerungsgerät, scheinen sich dort für einen Angriff auf die Geisterlande zu sammeln. Auf keinen Fall dürfen sie Erfolg haben.", sourceObjective = "Lady Liadrin in Silbermond möchte, dass Ihr 3 Fleischwagen der Geißel zerstört und 15 Belagerungsingenieure der Geißel tötet.", progress = "Willkommen zurück, {name}. Habt Ihr die Geißel und ihre Fleischwagen zurückgeschlagen?", completion = "Ihr habt Loyalität gegenüber Eurer Heimat und Eure Aufopferungsbereitschaft für die Ziele des Ordens bewiesen, {name}.  Ich habe noch eine letzte Aufgabe für Euch, bevor Ihr den Titel eines Meisters für Euch beanspruchen dürft.", sourceObjectiveStatus = "unverified-source-field" }
quests[64143] = { id = 64143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahre Meister des Lichts", description = "Ein Meister der Blutritter besitzt unglaubliche Fähigkeiten das Licht auf eine Art zu nutzen und zu formen, wie es die sogenannten anderen 'Paladine' nie verstehen werden. Das hält sie jedoch nicht davon ab, uns dafür zu ächten, wie wir das wahre Potential des Lichts entfesseln.\n\nWir müssen ihnen klar machen, dass man mit Unseresgleichen keine Spielchen spielt. Was ich mir vorgestellt habe, ist keine schnelle Angelegenheit und auch nicht einfach, doch wenn Ihr Euch dieser Aufgabe verpflichtet, wird es Euer erstes Ziel sein, den Bibliotheksflügel der Abtei von Tyrs Hand zu infiltrieren und eine Phiole heiligen Wassers von Tyrs Hand an Euch zu bringen.", sourceObjective = "Bringt Lady Liadrin in Silbermond eine Phiole Weihwasser von Tyrs Hand.", progress = "Habt Ihr das Wasser bekommen?", completion = "Hmm... das ist eine recht kleine Menge, doch wenn wir vorsichtig vorgehen, sollte es ausreichen. Seht Ihr, der Scharlachrote Kreuzzug behauptet von sich noch immer, dem Licht zu dienen. Ich nehme an, dass sie das auch auf eine recht verdrehte Art und Weise noch immer tun, und genau diesen Umstand möchte ich ausnutzen.\n\nIhr fehlgeleiteter Eifer hat selbst den Segen dieses Wassers korrumpiert und das macht es ideal für meine Zwecke.", sourceObjectiveStatus = "unverified-source-field" }
quests[64144] = { id = 64144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahre Meister des Lichts", description = "Jetzt, da wir das Wasser haben, benötigen wir eine Reihe von Zutaten in genau abgestimmten Mengen. Einige dieser Substanzen sind äußerst selten und wertvoll, {name}, doch ich habe Quellen für zwei von ihnen ausfindig gemacht.\n\n Ihr solltet einige arkane Katalysatoren bei Zalle, dem Reagenzienverkäufer in einem der Geschäfte auf dem Platz nahe der Todesschneise, bekommen. Darlia, die Giftlieferantin nahe der Schurkenausbilder in der Mördergasse, sollte über einen Vorrat an krepuskularem Pulver verfügen.\n\nUm meine Mixtur zu vervollständigen, benötige ich außerdem noch einen azerothischen Diamanten und einen makellosen schwarzen Diamanten.", sourceObjective = "Bringt Lady Liadrin in Silbermond 1 arkanen Katalysator, 1 Einheit krepuskulares Pulver, 1 azerothischen Diamanten und 1 makellosen schwarzen Diamanten.", progress = "Habt Ihr die von mir benötigten Zutaten bekommen?", completion = "Jetzt, wo wir über alle Zutaten verfügen, kann ich die Mixtur vorbereiten.\n\n<Ein Lächeln breitet sich langsam über Lady Liadrins Gesicht aus.>\n\nAlles entwickelt sich perfekt, {name}. Sobald ich hier fertig bin, werde ich Euch unseren letzten Schritt ausführlich erläutern.", sourceObjectiveStatus = "unverified-source-field" }
quests[64217] = { id = 64217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dunkle Portal", description = "Es existiert ein höllisches Tor, das jahrelang geruht hat. Jetzt ruht es nicht mehr.\n\nAlle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich in den Verwüsteten Landen zu melden. Begebt Euch zum Zeppelinmeister vor den Toren Orgrimmars und fliegt zum Basislager Grom'gol. Sprecht dort mit Thysta, um einen Flug nach Steinard zu erhalten.\n\nMeldet Euch umgehend bei Kriegsherr Dar'toon. Er erwartet Euch vor dem Dunklen Portal...", sourceObjective = "Macht Kriegsherr Dar'toon ausfindig. Er erwartet Eure Ankunft vor dem Dunklen Portal.", completion = "Willkommen zum Alptraum!", sourceObjectiveStatus = "unverified-source-field" }
quests[64319] = { id = 64319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Studie der Macht", description = "Haltet mich nicht für übermäßig grausam, {name}. Stillstreich hat sehr wohl gewusst, worauf er sich einlässt. Er verstand und akzeptierte seine Pflicht und wurde so ein leuchtendes Vorbild für alle aufstrebenden Blutritter.\n\nMeine Worte sind nicht als Grabesrede gedacht, {name}. Stillstreichs Dienste für uns gehören noch lange nicht der Vergangenheit an und Ihr werdet das Instrument seiner Wiederauferstehung sein.\n\nEure Ausbildung in der Verwendung des Lichts hat sich bisher auf einfache Zauber und Tricks beschränkt. Es wird Zeit, dass Ihr die wahre Natur und Tiefe unserer Macht kennen lernt. Sucht Magister Astalor Blutschwur auf.", sourceObjective = "Sprecht mit Magister Astalor Blutschwur in der Geheimen Kammer unter dem Hauptquartier der Blutelfen.", completion = "Willkommen junger {class}.\n\nBlutritter beziehen ihre Kraft von einem Wesen immenser Macht.\n\n\n\nIst es nicht glorreich? Es war ein Geschenk von unserem geliebten Prinz Kael'thas und ist die Grundlage der Macht der Blutritter über das Licht. Diese Kreatur möchte uns diese Macht vorenthalten, also haben wir eine Methode erfunden, sie ihr zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64845] = { id = 64845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsvorbereitungen der Allianz", description = "Ein Krieg steht uns bevor und die Allianz braucht mehr Kämpfer, um die Horde zu besiegen!\n\nUnsere Mission lautet, ihre Einsätze auf allen Schlachtfeldern zu vereiteln.\n\nIhr wollt Euch den Soldaten anschließen, oder?", sourceObjective = "Gewinnt eine Schlacht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte oder in Shattrath.", progress = "Wie ist die Lage, {name}? Gibt es Neuigkeiten von der Front?", completion = "Das sind gute Neuigkeiten, {class}! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65221] = { id = 65221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "1 instabiles Fläschchen des Zauberhexers für 10 Apexissplitter erwerben", sourceObjective = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomenlösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel.", sourceObjectiveStatus = "unverified-source-field" }
quests[65223] = { id = 65223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "1 instabiles Fläschchen der Bestie für 10 Apexissplitter erwerben" }
quests[65284] = { id = 65284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Gumbokessel", sourceObjective = "Grüße, {class}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch etwas auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals diesen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Booty Bay abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65285] = { id = 65285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Gumbokessel" }
quests[65561] = { id = 65561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock der Flamme", sourceObjective = "Grüße, {class}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch etwas auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals diesen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65562] = { id = 65562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock der Flamme", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnung im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diesen Gegenstand jemals verlieren, kommt zu mir zurück, und ich ersetze ihn Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[65593] = { id = 65593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzen der Liebenden", description = "Ein Inkubus wird von den Herzen Liebender angelockt. Die sehnlichste Liebe erschafft einen unwiderstehlichen Köder.\n\nMeine Wahrsagung hat mir zwei Personen gezeigt, die ganz besonders geeignet sein sollten.\n\nIm Silberwald bietet Avelina Lilly den gefallenen Magiern von Mühlenbern ihre Dienste als Schneiderin an. Im Brachland hofft Isaac Pearson, sich im Küstendorf Ratschet einen Namen zu machen.\n\nSie arbeiten an entgegengesetzten Enden der Welt, doch ihre Herzen sehnen sich nur nach einander. Bringt ihre Herzen zu Carendin.", sourceObjective = "Bringt die Herzen von Avelina Lilly und Isaac Pearson zu Carendin Halgar im Tempel der Verdammten.", progress = "Ah, {name}, Ihr seid zurückgekehrt. Konntet Ihr die Herzen der Liebenden beschaffen?", completion = "Hervorragend gemacht, wie erwartet, {name}.\n\n\n\nTrottel.", sourceObjectiveStatus = "unverified-source-field" }
quests[65597] = { id = 65597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Endlich ist es so weit. Bringt die Herzen zum Beschwörungskreis dort unten. Legt sie in die Mitte und ruft den Inkubus herbei.\n\nDer Dämon wird wenig erfreut sein, wenn er merkt, dass Ihr ihn in eine Falle gelockt habt. Lasst Euch nicht von ihm bezaubern, {name}. Ihr müsst ihn vollständig unterwerfen.\n\nErst dann kann ich Euch den Zauber lehren, mit dem Ihr ihn an Euren Willen bindet.Ihr erlernt:", sourceObjective = "Beschwört mit den Herzen der Liebenden einen Inkubus, unterwerft ihn und bringt die Herzen der Liebenden dann zu Carendin Halgar im Magieviertel von Unterstadt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[65601] = { id = 65601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebe kann schmerzhaft sein", description = "Einen männlichen Sayaad nennt man einen Inkubus. Eine äußerst boshafte Kreatur, die nur eines im Sinn hat.\n\nDer Dämon muss mit einem Köder in unsere Welt gelockt werden, mit einem Gegenstand, der starke Liebe und Hingabe verkörpert.\n\nWenn Ihr Euch von einem Blinden führen lassen möchtet, {name}, dann hört zu. Östlich von der Kluft der Schatten, in der Gasse von Orgrimmar, lebt Magar. Er wartet darauf, dass sein Lebensgefährte Krilge zurückkehrt.\n\nGeht zu ihm. Er wird Euch bitten, etwas Wertvolles zu suchen. Dies wird der Schlüssel sein, den Ihr dann Gan'rul bringen müsst.", sourceObjective = "Sprecht mit Magar in Orgrimmar.", completion = "Wer hat Euch von Krilge erzählt? Habt Ihr Neuigkeiten? Ihr treibt hoffentlich keine Spielchen mit mir...", sourceObjectiveStatus = "unverified-source-field" }
quests[65602] = { id = 65602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles aus Liebe", description = "Ihr werdet ein mächtiges Reagenz brauchen, um einen Inkubus anzulocken. Ein Objekt, das große Hingabe und Liebe verkörpert.\n\nDurch Wahrsagung habe ich eine kleine Statuette ausfindig gemacht, die für Euer Ritual geeignet sein sollte.\n\nVor Jahrtausenden gehörte die Figur einem jungen Paar. Die ursprünglichen Eigentümer sind verstorben, doch dieses Andenken besteht bis heute.\n\nFolgt der Straße nach Norden in das Eschental, dann Richtung Westen und an Maestras Posten vorbei. Ihr werdet ein Haus zwischen den Bäumen sehen. Dort findet Ihr, was Ihr sucht.", sourceObjective = "Beschafft die Holzstatuette und bringt sie zu Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", progress = "Ihr seid zurück. Darf ich davon ausgehen, dass Ihr Erfolg hattet?", completion = "<Gakin dreht und wendet die Holzstatuette in seiner Hand.>\n\nIch kann die Energie der Emotionen in diesem Artefakt spüren. Die Zeit konnte ihm nichts anhaben. Es wird den Inkubus anlocken wie eine Blüte die Biene.\n\nAuf Takar kann man sich verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65603] = { id = 65603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Es ist so weit. Nehmt die Statuette und steigt in die Gruft hinab. Ein Beschwörungskreis ist bereits vorbereitet. Ihr müsst die Statuette in der Mitte platzieren.\n\nDann wird sich das Tor öffnen und der Inkubus wird in unsere Welt kommen.\n\nIhr dürft einen Sayaad nicht unterschätzen. Der Dämon wird Euch angreifen, sobald er Eure Täuschung bemerkt. Ihr müsst alles einsetzen, was Ihr gelernt habt, um ihn zu besiegen.\n\nWenn Ihr Erfolg habt, kehrt zu mir zurück und ich unterwerfe die Kreatur Eurem Willen. Wenn Ihr versagt, ist Eure Seele verwirkt.", sourceObjective = "Beschwört mit Hilfe der Holzstatuette einen Inkubus, unterwerft ihn und bringt dann die Holzstatuette zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", progress = "Der Inkubus wird versuchen, Euch zu betören, zu täuschen und so zu überrumpeln. Der Dämon weiß genau, wie er die Herzen Sterblicher für sich gewinnt.\n\nDenkt daran, dass alle seine Versprechen Lügen sind. Für diesen Dämon seid Ihr nichts als Beute.", completion = "Nicht übel, {name}. Ihr habt das Scheusal bezwungen und Euer Wille blieb ungebrochen.\n\nManch ein Hexenmeister hielt sich schon für stark genug, einen Sayaad an sich zu binden, und endete stattdessen als nächste Mahlzeit des Dämons. Es freut mich, dass Ihr nicht so töricht seid.\n\nSeht genau zu, dann lehre ich Euch die Anrufung, mit der Ihr Euren jetzt unterworfenen Inkubus beschwört.", sourceObjectiveStatus = "unverified-source-field" }
quests[65604] = { id = 65604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Ja... verstehe. Ich kann die verbleibenden Emotionen spüren, die in diesem Stoff enthalten sind. Er ist mit Liebe verwoben. Dem wird der Inkubus nicht widerstehen können.\n\nBringt dies zum Beschwörungskreis in Neerus Zelt, {name}. Beschwört einen boshaften Inkubus und zeigt ihm, dass Ihr Eure Fähigkeiten gemeistert habt. Rechnet damit, dass er sich nicht still und leise unterwerfen lässt. Haltet Eure Magie bereit und macht Euch auf einen Kampf gefasst. Schon so mancher Hexenmeister hat seinen letzten Fehler begangen, indem er einen Dämon unterschätzt hat.\n\nBringt den Stoff zu mir zurück, sobald Ihr ihn bezwungen habt. Ich werde Magar sagen, was Ihr herausgefunden habt.", sourceObjective = "Beschwört mithilfe des abgetragenen Schals einen Inkubus, unterwerft ihn und bringt dann den abgetragenen Schal zu Gan'rul Blutauge in Orgrimmar zurück.", progress = "Die Sayaad unterwerfen den Verstand und quälen Seelen. Ihr Antlitz erfreut das Herz, sodass Ihr wehrlos seid, wenn sie mit Peitschen und Klauen in Euer Fleisch reißen.\n\nLasst Euch vom Inkubus nicht betören, {name}. Tötet ihn schnell und bringt es zu Ende.", completion = "Ha! Siegreich, wie ich es erwartet hatte!\n\nDer Inkubus wurde bezwungen, und ich werde Euch mit Freuden lehren, wie man den Dämon beschwört. Ihr werdet stärker und steht zweifelsohne davor, noch größere Macht zu erschließen.\n\nIch werde Magar den Schal zurückbringen. Ich kenne diesen Orc schon seit vielen Jahren und hätte nie gedacht, dass ihm einmal jemand so wie Krilge am Herzen liegen würde.\n\nDas erinnert uns daran, was uns von den Dämonen unterscheidet. Wir nutzen ihre Dunkelheit, lassen uns aber niemals von ihnen nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65610] = { id = 65610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwo anders", description = "Ich habe Krilge bei der Herstellung von Mondstoff im Eschental kennengelernt. Er war dort stationiert, um Zivilisten vor Gefahren zu beschützen, bis er dann verschwand...\n\nSie haben die Suche aufgegeben und sehen ihn als Deserteur, aber das glaube ich nicht.\n\nWir haben uns oft am Himmelssturzsee getroffen, bevor der von diesen aggressiven Sumpfmonstern überrannt wurde.\n\nIch bitte nur ungern andere um Gefallen, aber wenn Ihr ins Eschental gehen und nach ihm Ausschau halten könntet, wäre ich Euch dankbar.", sourceObjective = "Untersucht den Himmelssturzsee im Eschental und erstattet Gan'rul Blutauge in Orgrimmar Bericht.", progress = "Ja, was gibt's?", completion = "Was habt Ihr da, {name}? Einen Schal aus... Mondstoff? Ihr wollt mich doch hoffentlich nicht bezirzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70354] = { id = 70354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nordendexpeditionsvorräte", sourceObjective = "Grüße, {name}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70395] = { id = 70395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Sturmwind, Hauptstadt der Allianz!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Sturmwind, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[70396] = { id = 70396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Orgrimmar, Hauptstadt der Horde!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Orgrimmar, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[70397] = { id = 70397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", progress = "Ich habe ein Überlebenspaket für Eure Abenteuer zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Macht guten Gebrauch davon.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[70398] = { id = 70398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber diese eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70401] = { id = 70401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, {name}!" }
quests[70411] = { id = 70411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Dockmeister", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung von König Varian Wrynn wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Allianz zur Erschaffung eines Stützpunkts auf dem heimtückischen Kontinent Nordend zu unterstützen.", sourceObjective = "Benutzt die Schriftrolle der Teleportation, um den Hafen zu erreichen, und sprecht dort mit dem Dockmeister.", completion = "Seid gegrüßt, {class}. Ein Schiff nach Nordend wird bald dort am Ende des Docks anlegen. Schwingt Euch hinauf und die Mannschaft wird Euch wohlbehütet in dieses eisige, grausige Land transportieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[70448] = { id = 70448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elitenordendexpeditionsvorräte", sourceObjective = "Grüße, {name}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70449] = { id = 70449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elitenordendexpeditionsvorräte", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnungen im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diese Gegenstände jemals verlieren, kommt zu mir zurück, und ich ersetze sie Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
