quests[82983] = { id = 82983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenruftafel", sourceObjective = "Nutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Sturmwind zu erreichen, und sprecht dort mit Melris Malagan.", sourceObjectiveStatus = "unverified-source-field" }
